#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Generate the small embedded font for firstboot's English error messages."""
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

WIDTH, HEIGHT = 7, 11
font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf', 11)
lines = [
    '/* SPDX-License-Identifier: MIT */',
    '/* Generated by generate-log-font.py; printable ASCII, one bit per pixel. */',
    f'enum {{ LOG_FONT_WIDTH = {WIDTH}, LOG_FONT_HEIGHT = {HEIGHT} }};',
    f'static const uint8_t log_font[95][{HEIGHT}] = {{',
]
for code in range(32, 127):
    glyph = Image.new('L', (WIDTH, HEIGHT))
    ImageDraw.Draw(glyph).text((0, -2), chr(code), font=font, fill=255)
    rows = [sum((1 << x) for x in range(WIDTH) if glyph.getpixel((x, y)) >= 96)
            for y in range(HEIGHT)]
    lines.append('    { ' + ', '.join(f'0x{row:02x}' for row in rows) + f' }}, /* 0x{code:02x} */')
lines.append('};')
Path(__file__).with_name('log-font.h').write_text('\n'.join(lines) + '\n')
